def SubscriptionReferencesActiveTopic():
    for sid in sub_status:
        if sub_status[sid] == "CONFIRMED":
            tid = sub_topic[sid]
            if tid in topic_status:
                if topic_status[tid] != "ACTIVE":
                    return False
    return True


# check: every "AVAILABLE" "sqs" "message" belongs to an "ACTIVE" "sqs" "queue"

def MessagesReferenceActiveQueues():
    for mid in msg_status:
        if msg_status[mid] == "AVAILABLE":
            qid = msg_queue[mid]
            if qid in queue_status:
                if queue_status[qid] != "ACTIVE":
                    return False
    return True


# check: an "sqs" "message" can only be delivered if a "CONFIRMED" "sns" "subscription" exists for the "sns" "topic"

def DeliveryRequiresConfirmedSubscription():
    for mid in msg_status:
        if msg_status[mid] == "AVAILABLE":
            qid = msg_queue[mid]
            found = False
            for sid in sub_status:
                if sub_status[sid] == "CONFIRMED":
                    if sub_queue[sid] == qid:
                        found = True
            if found == False:
                return False
    return True
